      return send(res, 200, layout({ title: "Log in \u00b7 Airshare", body: `<div class="box" id="loginpage" data-tg="${authOn() ? 1 : 0}"><h2>Log in</h2><p class="m">Opening the login window...</p><noscript><p class="m">Please enable JavaScript to log in.</p></noscript></div>` }), "no-store");
