    const head = (back) => `<div class="sh" id="sh">${back ? `<a class="rb" id="backb" href="${backHref}" aria-label="Back"><i class="fa-solid fa-arrow-left"></i></a>` : ""}
<div class="sc">${smIco}<div class="st"><b id="hn">${esc(item.name)}</b><code id="hb">${esc(item.bundleIdentifier || "")}</code></div></div>
<a class="rb" href="/" aria-label="Close" onclick="location.replace('/');return false"><i class="fa-solid fa-xmark"></i></a></div><div class="shsp"></div><script>(function(){var h=document.getElementById('sh');if(h)document.body.appendChild(h);})();</script>`;
    let body;
