      const inner = `<div class="sec"><h2>Certificate</h2><p class="m">${certs.length ? "Your certificates have expired." : "Import a certificate to sign."}</p><div class="btnrow"><a class="abtn" href="/signer"><i class="fa-solid fa-plus"></i> Import certificate</a></div></div>`;
