 var id=[];if(o.name)id.push('Name \u2192 '+o.name);if(o.bundle)id.push('Bundle ID \u2192 '+o.bundle);if(o.ver)id.push('Version \u2192 '+o.ver);if(o.icon)id.push('Icon replaced');
