 grp('fa-key','Entitlements',o.scrub.map(function(x){return 'Remove '+LBL.scrub[x];}));
 grp('fa-plug','Libraries',o.dylibs.map(function(x){return '@executable_path/'+x.name;}));
 grp('fa-sliders','Build options',Object.keys(o.gen).map(function(x){return LBL.gen[x];}));
