  const upsert = db.prepare(`INSERT INTO downloads(bundle_id,version,day,n) VALUES(?,?,?,1)
    ON CONFLICT(bundle_id,version,day) DO UPDATE SET n=n+1`);
  // one counted download per visitor per app (any version)
  function countDownload(req, key, ver) {
    if (!isHumanGet(req)) return;
    try {
      // website: one per visitor per app; iOS app (sends its ADID): every download counts
      if (appAdid(req) || dlSeen.run(key, visitorHash(req)).changes) upsert.run(key, ver, new Date().toISOString().slice(0, 10));
    } catch (e) { console.warn("Download count failed:", e.message); }
  }
  function download(req, res) {
    const key = req.params.key, item = d.byKey(key);
    if (!item) return notFound(res);
    let url, ver;
    if (req.params.version) {
      const v = d.versionsOf(item).find(x => x.version === req.params.version);
      if (!v) return notFound(res);
      url = v.url; ver = v.version;
    } else {
      url = safeHttps(item.downloadURL); ver = d.verOf(item);
    }
    if (!url) return notFound(res);
    countDownload(req, key, ver);
    res.set({ "Cache-Control": "no-store", "X-Robots-Tag": "noindex, nofollow", "Referrer-Policy": "no-referrer" });
    return res.redirect(302, url);
  }
